      out.write("function getNextWeek(v,t){ \r\n");
      out.write("    var str=new Array(); \r\n");
      out.write("    var b=v.split(\"-\");\r\n");
      out.write("    var c=new Date(b[0],b[1]-1,b[2]); \r\n");
      out.write("    var d=c.valueOf()+1000*60*60*24*t;\r\n");
      out.write("    var e=new Date(d); \r\n");
      out.write("    \r\n");
      out.write("    str[str.length]=e.getYear(); \r\n");
      out.write("    str[str.length]=e.getMonth()+1; \r\n");
      out.write("    str[str.length]=e.getDate(); \r\n");
      out.write("    return str.join(\"\"); \r\n");
      out.write("}\r\n");
